use std::ffi::c_void;
use anyhow::Result;

/// Interface para el proveedor de lectura de tensores desde disco hacia RAM Pinned
pub trait TensorStorageProvider: Send + Sync {
    /// Lee los bytes correspondientes a una capa en un puntero de memoria Host Pinned previamente reservado
    unsafe fn read_layer_bytes(
        &self,
        layer_idx: usize,
        host_pinned_ptr: *mut u8,
        size_bytes: usize,
    ) -> Result<()>;
}

/// Interface para la gestión de la tubería de doble búfer en CUDA
pub trait CudaPipelineManager {
    /// Inicia la transferencia asíncrona de la siguiente capa hacia el buffer de VRAM secundario
    unsafe fn transfer_layer_async(
        &mut self,
        layer_idx: usize,
        host_pinned_ptr: *const u8,
        dev_buffer_ptr: *mut c_void,
        size_bytes: usize,
    ) -> Result<()>;

    /// Conmuta los búferes de la VRAM y sincroniza el stream de cómputo con el de transferencia
    fn swap_and_synchronize(&mut self) -> Result<()>;

    /// Invocación del kernel de inferencia para la capa activa
    fn launch_layer_execution(
        &self,
        layer_idx: usize,
        dev_buffer_ptr: *const c_void,
    ) -> Result<()>;
}
